let Lookback = 7d;
let WindowSec = 1800;
let RmmBinaries = dynamic(["ScreenConnect.ClientService.exe","ScreenConnect.WindowsClient.exe","ScreenConnect.ClientSetup.exe","AteraAgent.exe","atera_setup.exe","Syncro.exe","Syncro.Service.Runner.exe","RemoteUtilities.exe","rutserv.exe","rutview.exe","SimpleHelp.exe","JWrapper-Remote Access.exe","kabuto.exe","RPort.exe","MeshAgent.exe"]);
let RmmDomains = dynamic(["screenconnect.com","connectwise.com","atera.com","syncromsp.com","rmansys.ru","remoteutilities.com","simple-help.com","meshcentral.com"]);
let Clicks = UrlClickEvents
    | where Timestamp > ago(Lookback)
    | where ActionType in ("ClickAllowed","ClickedThrough")
    | where Url has_any ("onedrive","sharepoint","drive.google","dropbox","mediafire","wetransfer","filebin","sendspace","discord","trycloudflare") or Url matches regex @"(?i)\.(zip|msi|exe|7z|rar|iso|img)(\?|$)"
    | project ClickTime = Timestamp, AccountUpn, ClickUrl = Url, NetworkMessageId;
let SuspectProcs = DeviceProcessEvents
    | where Timestamp > ago(Lookback)
    | where FileName in~ (RmmBinaries) or InitiatingProcessFileName in~ (RmmBinaries)
    | where AccountName !endswith "$"
    | project ProcTime = Timestamp, DeviceName, AccountUpn, RmmBinary = FileName, ProcessCommandLine, InitiatingProcessFileName, InitiatingProcessCommandLine, FolderPath, SHA256;
SuspectProcs
| join kind=inner Clicks on AccountUpn
| where ProcTime between (ClickTime .. ClickTime + WindowSec * 1s)
| extend DelaySec = datetime_diff('second', ProcTime, ClickTime)
| project ClickTime, ProcTime, DelaySec, DeviceName, AccountUpn, ClickUrl, RmmBinary, ProcessCommandLine, InitiatingProcessFileName, FolderPath, SHA256
| order by ClickTime desc
